        internal void StorageActivityCanvas_MouseMove(object sender, System.Windows.Input.MouseEventArgs e)
        {
            var canvas = FindName("StorageActivityCanvas") as System.Windows.Controls.Canvas;
            if (canvas == null || _storageActR.Count < 2) return;
            double w = canvas.ActualWidth;
            if (w < 4) return;
            var pos = e.GetPosition(canvas);
            var rArr = _storageActR.ToArray();
            var wArr = _storageActW.ToArray();
            int idx = Math.Clamp((int)(pos.X / w * (rArr.Length - 1)), 0, rArr.Length - 1);
            float r  = idx < rArr.Length ? rArr[idx] : 0f;
            float wr = idx < wArr.Length ? wArr[idx] : 0f;
            canvas.ToolTip = $"R: {FormatKBps(r)}  W: {FormatKBps(wr)}";
        }

        internal void StorageActivityCanvas_MouseLeave(object sender, System.Windows.Input.MouseEventArgs e)
        {
            if (FindName("StorageActivityCanvas") is System.Windows.Controls.Canvas canvas)
                canvas.ToolTip = null;
