        // ── Mapping canvas → chart data for universal hover ──────────────────
        // Populated lazily on first use
        private readonly Dictionary<System.Windows.Controls.Canvas,
            (float[] data, float yMin, float yMax, string unit, string fmt)>
            _stressCanvasMap = new();

        private void EnsureStressCanvasMap()
        {
            if (_stressCanvasMap.Count > 0) return;
            // Map each visible canvas to its data array and Y scale
            void Add(System.Windows.Controls.Canvas? c, float[] d,
                     float mn, float mx, string u, string f)
            { if (c != null) _stressCanvasMap[c] = (d, mn, mx, u, f); }

            Add(FindName("CpuTempCanvas") as System.Windows.Controls.Canvas,
                _chartCpu,      20f, 100f, "°",   "F0");
            Add(FindName("CpuFreqCanvas") as System.Windows.Controls.Canvas,
                _chartCpuFreq,   0f,   0f, "MHz", "F0");
            Add(FindName("CpuUsageCanvas") as System.Windows.Controls.Canvas,
                _chartCpuUsage,  0f, 100f, "%",   "F0");
            Add(FindName("GpuTempCanvas") as System.Windows.Controls.Canvas,
                _chartGpu,      20f, 100f, "°",   "F0");
        }

        // Shared hover overlays per canvas (created on demand)
        private readonly Dictionary<System.Windows.Controls.Canvas,
            (System.Windows.Shapes.Line line,
             System.Windows.Controls.Border popup,
             System.Windows.Controls.TextBlock txt)>
            _stressHoverOverlays = new();

        internal void StressChart_MouseMove(object sender, System.Windows.Input.MouseEventArgs e)
        {
            if (sender is not System.Windows.Controls.Canvas canvas) return;
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            if (!double.IsFinite(w) || w < 4 || !double.IsFinite(h) || h < 4) return;

            EnsureStressCanvasMap();
            if (!_stressCanvasMap.TryGetValue(canvas, out var info)) return;

            // Create overlay elements on demand
            if (!_stressHoverOverlays.TryGetValue(canvas, out var ov))
            {
                var accentClr = (TryFindResource("AccentColor") as WpfColor?) ?? WpfColor.FromRgb(59, 130, 246);
                var line = new System.Windows.Shapes.Line
                {
                    Stroke           = new SolidColorBrush(WpfColor.FromArgb(160, accentClr.R, accentClr.G, accentClr.B)),
                    StrokeThickness  = 1,
                    StrokeDashArray  = new System.Windows.Media.DoubleCollection { 3, 3 },
                    IsHitTestVisible = false,
                    Visibility       = Visibility.Collapsed,
                };
                var txt = new System.Windows.Controls.TextBlock
                {
                    FontSize   = Ui.FontXS,
                    FontWeight = FontWeights.SemiBold,
                    Foreground = System.Windows.Media.Brushes.White,
                    Padding    = new Thickness(6, 3, 6, 3),
                };
                var pop = new System.Windows.Controls.Border
                {
                    Background      = new SolidColorBrush(WpfColor.FromArgb(200, 15, 23, 42)),
                    CornerRadius    = new CornerRadius(5),
                    Child           = txt,
                    IsHitTestVisible= false,
                    Visibility      = Visibility.Collapsed,
                };
                canvas.Children.Add(line);
                canvas.Children.Add(pop);
                ov = (line, pop, txt);
                _stressHoverOverlays[canvas] = ov;
            }

            const double pL = 10, pR = 8, pT = 16, pB = 14;
            double cW = w - pL - pR, cH = h - pT - pB;
            var pos = e.GetPosition(canvas);
            double mx = pos.X;
            if (mx < pL || mx > pL + cW) { StressChart_MouseLeave(sender, null!); return; }

            // Determine value at mouse X
            float yMin = info.yMin, yMax = info.yMax;
            if (yMax <= 0)
            {
                float maxVal = 0;
                for (int k = 0; k < Math.Min(_chartIdx, ChartMaxPoints); k++)
                {
                    float v = info.data[(_chartIdx - 1 - k + ChartMaxPoints) % ChartMaxPoints];
                    if (!float.IsNaN(v) && v > maxVal) maxVal = v;
                    if (k >= 300) break;
                }
                yMax = maxVal <= 0 ? 1 : (float)Math.Ceiling(maxVal * 1.25f / 10f) * 10f;
                yMin = 0;
            }

            // The same mapping as when drawing (DrawSlotChart): StressChartPoints across the width, data aligned to the right while
            // the buffer is not full.
            double xFrac  = (mx - pL) / cW;
            int displayPts = Math.Min(_chartIdx, StressChartPoints);
            int slot   = (int)Math.Round(xFrac * (StressChartPoints - 1));
            int ptIdx  = slot - (StressChartPoints - displayPts);
            float val  = float.NaN;
            long sampleIdx = -1;
            if (ptIdx >= 0 && ptIdx < displayPts)
            {
                int dataPos = (_chartIdx - displayPts + ptIdx + ChartMaxPoints * 2) % ChartMaxPoints;
                val = info.data[dataPos];
                sampleIdx = _chartIdx - displayPts + ptIdx;
            }
            // Stress test active at the point under the mouse (for the tooltip)
            string stressHover = "";
            if (sampleIdx >= 0)
                foreach (var iv in _stressIntervals)
                {
                    long ivEnd = iv.End < 0 ? _chartIdx - 1 : iv.End;
                    if (sampleIdx >= iv.Start && sampleIdx <= ivEnd)
                        stressHover += (stressHover.Length > 0 ? " + " : "") + iv.Kind + " stress";
                }

            // Draw crosshair line
            ov.line.X1 = ov.line.X2 = mx;
            ov.line.Y1 = pT; ov.line.Y2 = pT + cH;
            ov.line.Visibility = Visibility.Visible;

            if (!float.IsNaN(val) && val > 0)
            {
                double pyVal = pT + cH * (1.0 - Math.Clamp((val - yMin) / (yMax - yMin), 0, 1));
                ov.txt.Text = val.ToString(info.fmt) + info.unit
                            + (stressHover.Length > 0 ? "\n" + stressHover : "");
                ov.popup.Visibility = Visibility.Visible;
                double popW = stressHover.Length > 0 ? 90 : 55, popH = stressHover.Length > 0 ? 36 : 22;
                double popX = Math.Min(mx + 6, w - popW - 4);
                double popY = Math.Max(pT, Math.Min(pyVal - popH / 2, pT + cH - popH));
                System.Windows.Controls.Canvas.SetLeft(ov.popup, popX);
                System.Windows.Controls.Canvas.SetTop(ov.popup, popY);
            }
            else
            {
                ov.popup.Visibility = Visibility.Collapsed;
            }
        }

        internal void StressChart_MouseLeave(object sender, System.Windows.Input.MouseEventArgs e)
        {
            if (sender is System.Windows.Controls.Canvas canvas
                && _stressHoverOverlays.TryGetValue(canvas, out var ov))
            {
                ov.line.Visibility  = Visibility.Collapsed;
                ov.popup.Visibility = Visibility.Collapsed;
            }
        }


        // ── Universal crosshair for the dashboard charts ─────────────
        private readonly System.Collections.Generic.Dictionary<System.Windows.Controls.Canvas,
            (System.Windows.Shapes.Line line, System.Windows.Controls.Border popup,
             System.Windows.Controls.TextBlock txt)> _dashHoverOverlays = new();

        internal void DashChart_MouseMove(object sender, System.Windows.Input.MouseEventArgs e)
        {
            if (sender is not System.Windows.Controls.Canvas canvas) return;
            double w = canvas.ActualWidth, h = canvas.ActualHeight;
            if (!double.IsFinite(w) || !double.IsFinite(h) || w < 4 || h < 4) return;

            if (!_dashHoverOverlays.TryGetValue(canvas, out var overlay))
            {
                var line = new System.Windows.Shapes.Line
                {
                    Stroke = new SolidColorBrush(WpfColor.FromArgb(140, 255, 255, 255)),
                    StrokeThickness = 1,
                    StrokeDashArray = new System.Windows.Media.DoubleCollection { 3, 3 },
                    IsHitTestVisible = false,
                    Visibility = Visibility.Collapsed
                };
                var txt = new System.Windows.Controls.TextBlock
                {
                    FontSize = Ui.FontXS, FontWeight = FontWeights.SemiBold,
                    Foreground = System.Windows.Media.Brushes.White,
                    Padding = new Thickness(6, 3, 6, 3)
                };
                var popup = new System.Windows.Controls.Border
                {
                    CornerRadius = new CornerRadius(4),
                    Background = new SolidColorBrush(WpfColor.FromArgb(210, 15, 22, 38)),
                    Child = txt, IsHitTestVisible = false,
                    Visibility = Visibility.Collapsed
                };
                canvas.Children.Add(line);
                canvas.Children.Add(popup);
                overlay = (line, popup, txt);
                _dashHoverOverlays[canvas] = overlay;
            }

            float[]? queue = null;
            string unit = ""; float yMin = 0f, yMax = 100f;

            if (canvas == SparkCpu)               { queue = _cCpu ?? _arrCpu;     unit = "%";    yMin = 0;  yMax = 100; }
            else if (canvas == SparkGpu)          { queue = _cGpu ?? _arrGpu;     unit = "%";    yMin = 0;  yMax = 100; }
            else if (canvas == SparkRam)          { queue = _cRam ?? _arrRam;     unit = "%";    yMin = 0;  yMax = 100; }
            else if (canvas == DashCpuTempChart)  { queue = _cCpuTemp ?? _arrCpuTemp; unit = "°C"; (yMin, yMax) = DashTempRange(canvas, queue); }   // the same scale as the drawn line
            else if (canvas == DashGpuTempChart)  { queue = _cGpuTemp ?? _arrGpuTemp; unit = "°C"; (yMin, yMax) = DashTempRange(canvas, queue); }
            else if (canvas == DashPingChart)     { queue = _cPing ?? _arrPing;    unit = " ms";   yMin = 0;  yMax = 100; }
            else if (canvas == SparkDiskActivity) { queue = _cDiskR ?? _arrDiskR;   unit = " KB/s"; yMin = 0;  yMax = -1; }
            else if (canvas == SparkNetActivity)  { queue = _cNetDown ?? _arrNetDown; unit = " KB/s"; yMin = 0;  yMax = -1; }

            if (queue == null || queue.Length < 2)
            {
                overlay.line.Visibility = Visibility.Collapsed;
                overlay.popup.Visibility = Visibility.Collapsed;
                return;
            }

            var data = queue.ToArray(); int n = data.Length;
            bool isTempChart = canvas == DashCpuTempChart || canvas == DashGpuTempChart;
            double pL = 2, pR = isTempChart ? 8 : 6, pT = 8, pB = 4;
            double cW = w - pL - pR, cH = h - pT - pB;
            var pos = e.GetPosition(canvas);
            double mx = Math.Clamp(pos.X, pL, pL + cW);
            double fraction = (mx - pL) / cW;
            int idx = Math.Clamp((int)Math.Round(fraction * (n - 1)), 0, n - 1);
            float val = data[idx];

            if (float.IsNaN(val) || float.IsInfinity(val))
            {
                overlay.line.Visibility = Visibility.Collapsed;
                overlay.popup.Visibility = Visibility.Collapsed;
                return;
            }

            float dynMax = yMax < 0
                ? Math.Max(1f, data.Where(v => !float.IsNaN(v)).DefaultIfEmpty(1f).Max() * 1.2f)
                : yMax;
            if (dynMax <= yMin) dynMax = yMin + 1f;
            double range = dynMax - yMin;
            double py = pT + cH - Math.Clamp((val - yMin) / range, 0, 1) * cH;
            double xPos = pL + fraction * cW;

            overlay.line.X1 = xPos; overlay.line.Y1 = pT;
            overlay.line.X2 = xPos; overlay.line.Y2 = pT + cH;
            overlay.line.Visibility = Visibility.Visible;

            string valStr = unit == "°C" ? TempUnit.Fmt(val, 1)
                : unit == " ms" ? $"{val:F1}{unit}"
                : unit == "%" ? $"{val:F0}{unit}"
                : FormatKBps(val);
            int secAgo = n - 1 - idx;
            string timeStr = secAgo == 0 ? PT("now") : $"-{secAgo}s";
            overlay.txt.Text = $"{valStr}  {timeStr}";

            WpfColor accent = canvas == DashCpuTempChart ? _penDashCpuTemp.Brush is SolidColorBrush cScb ? cScb.Color : WpfColor.FromRgb(56, 138, 221)
                : canvas == DashGpuTempChart ? _penDashGpuTemp.Brush is SolidColorBrush gScb ? gScb.Color : WpfColor.FromRgb(56, 138, 221)
                : canvas == SparkCpu
                ? WpfColor.FromRgb(59, 130, 246)
                : canvas == SparkGpu
                ? WpfColor.FromRgb(249, 115, 22)
                : canvas == SparkRam ? WpfColor.FromRgb(34, 197, 94)
                : canvas == DashPingChart ? WpfColor.FromRgb(168, 85, 247)
                : WpfColor.FromRgb(245, 158, 11);
            overlay.line.Stroke = new SolidColorBrush(WpfColor.FromArgb(120, accent.R, accent.G, accent.B));
            overlay.txt.Foreground = new SolidColorBrush(accent);

            overlay.popup.Measure(new System.Windows.Size(double.PositiveInfinity, double.PositiveInfinity));
            double popW = overlay.popup.DesiredSize.Width, popH = overlay.popup.DesiredSize.Height;
            double popX = xPos + 8; if (popX + popW > w - 4) popX = xPos - popW - 8;
            double popY = Math.Clamp(py - popH / 2, pT, pT + cH - popH);
            System.Windows.Controls.Canvas.SetLeft(overlay.popup, popX);
            System.Windows.Controls.Canvas.SetTop(overlay.popup, popY);
            overlay.popup.Visibility = Visibility.Visible;
        }

        internal void DashChart_MouseLeave(object sender, System.Windows.Input.MouseEventArgs e)
        {
            if (sender is System.Windows.Controls.Canvas canvas
                && _dashHoverOverlays.TryGetValue(canvas, out var overlay))
            {
                overlay.line.Visibility = Visibility.Collapsed;
                overlay.popup.Visibility = Visibility.Collapsed;
            }
        }

        /// <summary>
        /// Snapshot export — saves the current state as JSON in a timestamped file.
        /// Called from the hero bar or from System Info.
        /// </summary>
        internal async void ExportSnapshot_Click(object sender, System.Windows.RoutedEventArgs e)
        {
            try
            {
                var snap = _lastTempSnap;
                var ts = DateTime.Now;
                string filename = $"SMDWin_Snapshot_{ts:yyyyMMdd_HHmmss}.json";
                string path = System.IO.Path.Combine(
                    SMDWin.Services.SettingsService.GetEffectiveReportFolder(), filename);

                var sb = new System.Text.StringBuilder();
                sb.AppendLine("{");
                sb.AppendLine($"  \"timestamp\": \"{ts:yyyy-MM-dd HH:mm:ss}\",");
                sb.AppendLine($"  \"machine\": \"{_summary?.Model ?? "Unknown"}\",");
                sb.AppendLine($"  \"os\": \"{_summary?.OsName ?? ""} Build {_summary?.OsBuild ?? ""} \",");
                sb.AppendLine($"  \"uptime\": \"{_summary?.Uptime ?? ""}\",");
                sb.AppendLine("  \"cpu\": {");
                sb.AppendLine($"    \"name\": \"{_summary?.Cpu ?? ""}\",");
                sb.AppendLine($"    \"load_pct\": {_cachedCpuPct:F1},");
                if (snap?.CpuTemp.HasValue == true)
                    sb.AppendLine($"    \"temp_c\": {snap.CpuTemp.Value:F1},");
                if (snap?.CpuFreqMHz.HasValue == true)
                    sb.AppendLine($"    \"freq_mhz\": {snap.CpuFreqMHz.Value:F0},");
                if (snap?.CpuPowerW.HasValue == true)
                    sb.AppendLine($"    \"power_w\": {snap.CpuPowerW.Value:F1},");
                sb.AppendLine("    \"_\": null");
                sb.AppendLine("  },");
                sb.AppendLine("  \"gpu\": {");
                sb.AppendLine($"    \"name\": \"{_summary?.GpuName ?? ""}\",");
                sb.AppendLine($"    \"load_pct\": {_cachedGpuPct:F1},");
                if (snap?.GpuTemp.HasValue == true)
                    sb.AppendLine($"    \"temp_c\": {snap.GpuTemp.Value:F1},");
                if (snap?.GpuMemUsedMB.HasValue == true)
                    sb.AppendLine($"    \"vram_used_mb\": {snap.GpuMemUsedMB.Value:F0},");
                sb.AppendLine("    \"_\": null");
                sb.AppendLine("  },");
                sb.AppendLine("  \"ram\": {");
                float ramPct = _cachedTotalRamMB > 0 ? Math.Clamp(100f*(1f - _cachedAvailRamMB/_cachedTotalRamMB), 0f, 100f) : 0f;
                sb.AppendLine($"    \"total_mb\": {_cachedTotalRamMB:F0},");
                sb.AppendLine($"    \"available_mb\": {_cachedAvailRamMB:F0},");
                sb.AppendLine($"    \"used_pct\": {ramPct:F1}");
                sb.AppendLine("  },");
                sb.AppendLine($"  \"network_down_kbps\": {_emaNetDown:F1},");
                sb.AppendLine($"  \"network_up_kbps\": {_emaNetUp:F1},");
                sb.AppendLine($"  \"ping_ms\": {(_dashPingMin > 0 ? _dashPingSum/_dashPingCount : 0):F1}");
                sb.AppendLine("}");

                await System.IO.File.WriteAllTextAsync(path, sb.ToString());

                // Notificare succes
                System.Windows.MessageBox.Show(
                    $"Snapshot salvat:\n{path}",
                    "SMDWin — Export", System.Windows.MessageBoxButton.OK,
                    System.Windows.MessageBoxImage.Information);
            }
            catch (Exception ex)
            {
                System.Windows.MessageBox.Show($"Eroare export: {ex.Message}", "SMD Win",
                    System.Windows.MessageBoxButton.OK, System.Windows.MessageBoxImage.Error);
            }
        }

